function maximumScore(nums, k) {
  const MOD = 1000000007n;
  const n = nums.length;
  let limit = 1;
  for (const value of nums) limit = Math.max(limit, value);
  const primeScore = new Array(limit + 1).fill(0);
  for (let p = 2; p <= limit; p++) {
    if (primeScore[p] > 0) continue;
    for (let multiple = p; multiple <= limit; multiple += p) {
      primeScore[multiple]++;
    }
  }
  const score = nums.map(value => primeScore[value]);
  const left = new Array(n).fill(-1);
  const right = new Array(n).fill(n);
  const stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && score[stack[stack.length - 1]] < score[i]) {
      right[stack.pop()] = i;
    }
    if (stack.length > 0) {
      left[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }

  function power(base, exponent) {
    let product = 1n;
    let factor = BigInt(base);
    while (exponent > 0) {
      if (exponent % 2 === 1) {
        product = product * factor % MOD;
      }
      factor = factor * factor % MOD;
      exponent = Math.floor(exponent / 2);
    }
    return product;
  }

  const order = nums.map((_, i) => i).sort((a, b) => nums[b] - nums[a]);
  let remaining = k;
  let result = 1n;
  for (const i of order) {
    if (remaining === 0) break;
    const ranges = (i - left[i]) * (right[i] - i);
    const take = Math.min(ranges, remaining);
    result = result * power(nums[i], take) % MOD;
    remaining -= take;
  }
  return Number(result);
}

