function maximumScore(nums, k) {
  // List the chosen element of every subarray, then multiply the k largest.
  const distinctPrimes = (x) => {
    let count = 0;
    for (let p = 2; p * p <= x; p++) {
      if (x % p === 0) {
        count++;
        while (x % p === 0) x /= p;
      }
    }
    return x > 1 ? count + 1 : count;
  };
  const scores = nums.map(distinctPrimes);
  const picks = [];
  for (let l = 0; l < nums.length; l++) {
    let best = l;
    for (let r = l; r < nums.length; r++) {
      if (scores[r] > scores[best]) best = r;
      picks.push(nums[best]);
    }
  }
  picks.sort((a, b) => b - a);
  let total = 1n;
  for (let t = 0; t < k; t++) total = total * BigInt(picks[t]) % 1000000007n;
  return Number(total);
}

