function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 8);
  const mode = Math.floor(rand() * 3);
  const pool = [1, 2, 3, 4, 6, 8, 9, 12, 30, 60, 97, 210, 2310, 30030, 99991, 100000];
  const nums = [];
  for (let i = 0; i < n; i++) {
    if (mode === 0) nums.push(1 + Math.floor(rand() * (large ? 100000 : 60)));
    else if (mode === 1) nums.push(pool[Math.floor(rand() * pool.length)]);
    else nums.push(large ? 1 + Math.floor(rand() * 100000) : 1 + Math.floor(rand() * 12));
  }
  if (large && mode === 2) nums.sort((a, b) => a - b);
  const most = Math.min(n * (n + 1) / 2, 1e9);
  const pick = rand();
  const k = pick < 0.2 ? most : pick < 0.4 ? 1 + Math.floor(rand() * n) : 1 + Math.floor(rand() * most);
  return [nums, k];
}
